import RNA
target='.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
n=106
pairs={}
st=[]
for i,c in enumerate(target):
    if c=='(': st.append(i)
    elif c==')':
        j=st.pop(); pairs[j]=i; pairs[i]=j
pairlist=sorted([(i,pairs[i]) for i in range(n) if i in pairs and i<pairs[i]])
print('pairs',pairlist)
# Lonely pairs: positions where neither i-1,j+1 nor i+1,j-1 form a stacked pair
def is_stacked(i,j):
    a=(i+1,j-1) in [tuple(p) for p in pairlist] or (i-1,j+1) in [tuple(p) for p in pairlist]
    return a
for i,j in pairlist:
    s = is_stacked(i,j)
    print(f'  ({i},{j}) stacked={s} {"LONELY" if not s else ""}')
